using System.Security.Cryptography;
using Shortener.Core.Ports;

namespace Shortener.Infrastructure;

public class EightCharacterAlphanumericCodeGenerator : IShortCodeGenerator
{
    private const string Chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    private const int CodeLength = 8;

    public string GenerateCode()
    {
        Span<byte> data = stackalloc byte[CodeLength];
        using (var rng = RandomNumberGenerator.Create())
        {
            rng.GetBytes(data);
        }

        char[] result = new char[CodeLength];
        for (int i = 0; i < CodeLength; i++)
        {
            result[i] = Chars[data[i] % Chars.Length];
        }
        return new string(result);
    }
}

using System.Collections.Concurrent;
using Shortener.Core;
using Shortener.Core.Ports;

namespace Shortener.Infrastructure;

public class InMemoryLinkRepository : ILinkRepository
{
    private readonly ConcurrentDictionary<string, Link> _linksByShortCode = new();
    private readonly ConcurrentDictionary<string, Link> _linksByLongUrl = new();

    public Task<Link?> FindByShortCodeAsync(string shortCode)
    {
        _linksByShortCode.TryGetValue(shortCode, out var link);
        return Task.FromResult(link);
    }

    public Task<Link?> FindByLongUrlAsync(string longUrl)
    {
        _linksByLongUrl.TryGetValue(longUrl, out var link);
        return Task.FromResult(link);
    }

    public Task SaveAsync(Link link)
    {
        _linksByShortCode.TryAdd(link.ShortCode, link);
        _linksByLongUrl.TryAdd(link.LongUrl, link);
        return Task.CompletedTask;
    }

    public Task IncrementUsageCountAsync(string shortCode)
    {
        _linksByShortCode.AddOrUpdate(
            shortCode,
            _ => throw new LinkNotFoundException(shortCode),
            (_, existingLink) => existingLink with { UsageCount = existingLink.UsageCount + 1 });
        // The _linksByLongUrl entry doesn't need updating as UsageCount is not part of its key
        return Task.CompletedTask;
    }
}

