using System.ComponentModel.DataAnnotations;

namespace Shortener.Api.Models;

public record CreateShortLinkRequest([Required] string Url);

using Shortener.Api.Models;
using Shortener.Core;
using Shortener.Core.Ports;
using Shortener.Infrastructure;
using Microsoft.AspNetCore.Diagnostics;
using Serilog;
using Microsoft.AspNetCore.Http.Extensions; // Required for GetDisplayUrl

public partial class Program { }

var builder = WebApplication.CreateBuilder(args);

// Configure Serilog for structured logging
Log.Logger = new LoggerConfiguration()
    .ReadFrom.Configuration(builder.Configuration)
    .Enrich.FromLogContext()
    .WriteTo.Console()
    .CreateLogger();

builder.Host.UseSerilog();

// Add services to the container.
builder.Services.AddEndpointsApiExplorer();
builder.Services.AddSwaggerGen();
builder.Services.AddHealthChecks();

builder.Services.AddSingleton<ILinkRepository, InMemoryLinkRepository>();
builder.Services.AddSingleton<IShortCodeGenerator, EightCharacterAlphanumericCodeGenerator>();
builder.Services.AddSingleton<ShortenerService>();

var app = builder.Build();

// Configure the HTTP request pipeline.
if (app.Environment.IsDevelopment())
{
    app.UseSwagger();
    app.UseSwaggerUI();
}

app.UseExceptionHandler(exceptionHandlerApp =>
{
    exceptionHandlerApp.Run(async context =>
    {
        var exceptionHandlerPathFeature =
            context.Features.Get<IExceptionHandlerPathFeature>();

        if (exceptionHandlerPathFeature?.Error is InvalidUrlException invalidUrlEx)
        {
            app.Logger.LogInformation("Invalid URL submitted: {Message}", invalidUrlEx.Message);
            context.Response.StatusCode = StatusCodes.Status400BadRequest;
            await context.Response.WriteAsJsonAsync(new
            {
                type = "https://tools.ietf.org/html/rfc7807",
                title = "Bad Request",
                status = StatusCodes.Status400BadRequest,
                detail = invalidUrlEx.Message
            });
            return;
        }

        if (exceptionHandlerPathFeature?.Error is LinkNotFoundException linkNotFoundEx)
        {
            app.Logger.LogInformation("Short code not found: {Message}", linkNotFoundEx.Message);
            context.Response.StatusCode = StatusCodes.Status404NotFound;
            await context.Response.WriteAsJsonAsync(new
            {
                type = "https://tools.ietf.org/html/rfc7807",
                title = "Not Found",
                status = StatusCodes.Status404NotFound,
                detail = linkNotFoundEx.Message
            });
            return;
        }

        app.Logger.LogError(exceptionHandlerPathFeature?.Error, "An unhandled exception occurred: {Path}", exceptionHandlerPathFeature?.Path);
        context.Response.StatusCode = StatusCodes.Status500InternalServerError;
        await context.Response.WriteAsJsonAsync(new
        {
            type = "https://tools.ietf.org/html/rfc7807",
            title = "Internal Server Error",
            status = StatusCodes.Status500InternalServerError,
            detail = "An unexpected error occurred."
        });
    });
});

app.UseHttpsRedirection();

// Health Check Endpoint (AC-7)
app.MapHealthChecks("/health");

// POST /links (AC-1, AC-6, AC-8)
app.MapPost("/links", async (CreateShortLinkRequest request, ShortenerService service, HttpContext httpContext) =>
{
    var (link, isNew) = await service.CreateShortLinkAsync(request.Url);

    // Construct the short URL based on the current request's host
    var shortUrl = UriHelper.BuildAbsolute(httpContext.Request.Scheme, httpContext.Request.Host, path: $"/{link.ShortCode}");

    var response = new ShortLinkResponse(link.ShortCode, shortUrl, link.UsageCount);

    if (isNew)
    {
        app.Logger.LogInformation("Created new short link for {LongUrl} with code {ShortCode}", link.LongUrl, link.ShortCode);
        return Results.Created(shortUrl, response);
    }
    else
    {
        app.Logger.LogInformation("Returned existing short link for {LongUrl} with code {ShortCode}", link.LongUrl, link.ShortCode);
        return Results.Ok(response); // Per D002
    }
})
.WithName("CreateShortLink")
.WithOpenApi();

// GET /{code} (AC-2, AC-3)
app.MapGet("/{code}", async (string code, ShortenerService service, HttpContext httpContext) =>
{
    var longUrl = await service.RetrieveOriginalUrlAsync(code);
    app.Logger.LogInformation("Redirecting short code {ShortCode} to {LongUrl}", code, longUrl);
    httpContext.Response.Redirect(longUrl, permanent: false);
    return Results.Empty; // Results.Redirect does a 302, but we need to increment count first
})
.WithName("RedirectShortLink")
.WithOpenApi();

// GET /links/{code}/stats (AC-4, AC-5)
app.MapGet("/links/{code}/stats", async (string code, ShortenerService service) =>
{
    var usageCount = await service.GetUsageStatsAsync(code);
    app.Logger.LogInformation("Retrieved stats for short code {ShortCode}: UsageCount = {UsageCount}", code, usageCount);
    return Results.Ok(new ShortLinkResponse(code, string.Empty, usageCount));
})
.WithName("GetLinkStats")
.WithOpenApi();

app.Run();

using Shortener.Infrastructure;
using FluentAssertions;
using Xunit;
using System.Linq;
using System.Threading.Tasks;

namespace Shortener.UnitTests;

public class EightCharacterAlphanumericCodeGeneratorTests
{
    private readonly EightCharacterAlphanumericCodeGenerator _sut;

    public EightCharacterAlphanumericCodeGeneratorTests()
    {
        _sut = new EightCharacterAlphanumericCodeGenerator();
    }

    [Fact]
    public async Task Given_Generator_When_GenerateCodeAsync_Then_ReturnsEightCharacterCode()
    {
        // Act
        var code = await _sut.GenerateCodeAsync();

        // Assert
        code.Should().NotBeNullOrEmpty();
        code.Length.Should().Be(8); // Per D003
    }

    [Fact]
    public async Task Given_Generator_When_GenerateCodeAsync_Then_ReturnsAlphanumericCode()
    {
        // Act
        var code = await _sut.GenerateCodeAsync();

        // Assert
        code.Should().MatchRegex("^[a-zA-Z0-9]{8}$"); // Per D003
    }

    [Fact]
    public async Task Given_Generator_When_GenerateMultipleCodes_Then_CodesAreUnique()
    {
        // Arrange
        var codes = new HashSet<string>();
        const int numberOfCodesToGenerate = 1000;

        // Act
        for (int i = 0; i < numberOfCodesToGenerate; i++)
        {
            codes.Add(await _sut.GenerateCodeAsync());
        }

        // Assert
        codes.Count.Should().Be(numberOfCodesToGenerate);
    }

    [Fact]
    public async Task Given_Generator_When_GenerateMultipleCodes_Then_CodesAreNotGuessable()
    {
        // This is a probabilistic test for 'unguessability' through randomness.
        // A true cryptographic test is complex and outside the scope of a simple unit test.
        // We are checking for a reasonable distribution, indicating random selection.
        var charCounts = new Dictionary<char, int>();
        const int numberOfCodes = 1000;
        const int expectedOccurrencesPerChar = numberOfCodes * 8 / 62; // 8 chars per code, 62 possible chars
        const double toleranceFactor = 0.5; // Allow for 50% deviation due to randomness with small sample size

        for (int i = 0; i < numberOfCodes; i++)
        {
            var code = await _sut.GenerateCodeAsync();
            foreach (char c in code)
            {
                charCounts.TryAdd(c, 0);
                charCounts[c]++;
            }
        }

        // Assert that characters are used with some distribution
        charCounts.Should().NotBeEmpty();
        foreach (var count in charCounts.Values)
        {
            count.Should().BeCloseTo(expectedOccurrencesPerChar, expectedOccurrencesPerChar * toleranceFactor);
        }

        // Ensure a good mix of characters (not just a few used repeatedly)
        charCounts.Keys.Count().Should().BeGreaterOrEqualTo(Chars.Length * 0.8); // At least 80% of possible characters used
    }
}

